#include <math.h>
#include <stdio.h>

static double heavy(long n) {
    double s = 0;
    for (long i = 1; i <= n; i++)
        s += sqrt((double)i) * sin((double)i);
    return s;
}

static double light(long n) {
    double s = 0;
    for (long i = 1; i <= n; i++)
        s += i * 0.5;
    return s;
}

int main(void) {
    double t = 0;
    for (int r = 0; r < 30; r++) {
        t += heavy(1500000);
        t += light(1500000);
    }
    printf("%f\n", t);
    return 0;
}
